@Entity
@RevisionEntity(CurrentUserRevisionListener.class)
public class CustomRevisionEntity extends DefaultRevisionEntity {
    private String changedBy;
}

public class CurrentUserRevisionListener implements RevisionListener {
    public void newRevision(Object entity) {
        ((CustomRevisionEntity) entity).setChangedBy(CurrentUser.get());
    }
}

